const __pageData = JSON.parse('{"title":"Xi Jinping","description":"","frontmatter":{"title":"Xi Jinping","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["china","sco","multipolar","bri"],"sources":["raw/a-gateway-to-a-new-world-of-cooperation.md","raw/badlands-blitz-episode-17.md","raw/badlands-brief-311.md","raw/badlands-brief-5a2.md","raw/badlands-brief-577.md","raw/badlands-brief-618.md","raw/badlands-brief-739.md","raw/badlands-brief-990.md","raw/badlands-brief-bb1.md","raw/badlands-brief-ea5.md","raw/badlands-news-brief-01d.md","raw/badlands-news-brief-02f.md","raw/badlands-news-brief-051.md","raw/badlands-news-brief-0ad.md","raw/badlands-news-brief-09e.md","raw/badlands-news-brief-0e0.md","raw/badlands-news-brief-0db.md","raw/badlands-news-brief-125.md","raw/badlands-news-brief-116.md","raw/badlands-news-brief-12a.md","raw/badlands-news-brief-1d7.md","raw/badlands-news-brief-204.md","raw/badlands-news-brief-27c.md","raw/badlands-news-brief-28e.md","raw/badlands-news-brief-4ee.md","raw/badlands-news-brief-520.md","raw/badlands-news-brief-61a.md","raw/badlands-news-brief-69b.md","raw/badlands-news-brief-688.md","raw/badlands-news-brief-6e6.md","raw/badlands-news-brief-7e0.md","raw/badlands-news-brief-889.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/xi-jinping.md","filePath":"entities/xi-jinping.md","lastUpdated":null}');
